library.go:
package native

import (
	"crypto/sha256"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	goruntime "runtime"
	"strings"
	"sync"
)

type runtimeFile struct {
	name     string
	contents []byte
}

// runtimeBuilds serializes builders of the same disk entry within this process. Different flag
// sets can build concurrently. Across processes, only a complete directory is published by rename.
var runtimeBuilds sync.Map

// RuntimeLibrary returns a cached static library compiled with Flags(options). An empty directory
// uses the embedded runtime; the fuzzer supplies another checkout's runtime directory instead.
// Sources and headers are snapshotted together, so the key and the compiled bytes cannot disagree.
func RuntimeLibrary(directory string, options Options) (string, error) {
	return runtimeLibrary(directory, options, nil)
}

func RuntimeLibraryForSource(directory string, source string, options Options) (string, error) {
	return runtimeLibrary(directory, options, featureFlags(source))
}

// sourceFlags compiles anything built for one program's emitted C: its runtime library, a split
// unit, the checker-archive build. It is the one home for those flags, so a new build path that
// starts from Flags(options) alone meets adamic.h's layouts without the program's features.
func sourceFlags(source string, options Options) []string {
	return append(Flags(options), featureFlags(source)...)
}

// featureFlags are the runtime features emitted C turns on with its leading #defines, as -D flags,
// so every unit compiled with that C (the runtime's own .c files, and a header included before
// those #defines) sees the same layouts.
func featureFlags(source string) []string {
	var flags []string
	for _, feature := range []string{"ADAMIC_CLOSURE_CONVENTION", "ADAMIC_CANONICAL_CLOSURES", "ADAMIC_CLOSURE_RECEIVERS", "ADAMIC_REGEXP_REPLACE_CALLBACK", "ADAMIC_NODE_HOST"} {
		if strings.Contains(source, "#define "+feature+" 1\n") {
			flags = append(flags, "-D"+feature+"=1")
		}
	}
	return flags
}

func runtimeLibrary(directory string, options Options, extraFlags []string) (string, error) {
	if err := ValidateOptions(options); err != nil {
		return "", err
	}
	var sources fs.FS = runtime
	root := "runtime"
	if directory != "" {
		sources, root = os.DirFS(directory), "."
	}
	files, err := readRuntime(sources, root)
	if err != nil {
		return "", fmt.Errorf("native: runtime: %w", err)
	}
	if !slicesContain(extraFlags, "-DADAMIC_REGEXP_REPLACE_CALLBACK=1") {
		kept := files[:0]
		for _, file := range files {
			if file.name != "regexp_replace.c" {
				kept = append(kept, file)
			}
		}
		files = kept
	}
	if !slicesContain(extraFlags, "-DADAMIC_NODE_HOST=1") {
		kept := files[:0]
		for _, file := range files {
			if file.name != "node_host.c" {
				kept = append(kept, file)
			}
		}
		files = kept
	}
	compiler, err := exec.LookPath(compilerName(options))
	if err != nil {
		return "", fmt.Errorf("native: %w", err)
	}
	version, err := exec.Command(compiler, "--version").CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("native: clang --version: %w\n%s", err, version)
	}
	cache, err := os.UserCacheDir()
	if err != nil {
		return "", fmt.Errorf("native: cache directory: %w", err)
	}
	return cachedRuntime(files, append(Flags(options), extraFlags...), compiler, string(version), filepath.Join(cache, "adamic", "runtime"))
}

func readRuntime(sources fs.FS, root string) ([]runtimeFile, error) {
	entries, err := fs.ReadDir(sources, root)
	if err != nil {
		return nil, err
	}
	var files []runtimeFile
	for _, entry := range entries {
		if entry.IsDir() || (!strings.HasSuffix(entry.Name(), ".c") && auditValue("M06", !strings.HasSuffix(entry.Name(), ".h"), !strings.HasSuffix(entry.Name(), ".hh"))) {
			continue
		}
		contents, err := fs.ReadFile(sources, path.Join(root, entry.Name()))
		if err != nil {
			return nil, err
		}
		files = append(files, runtimeFile{entry.Name(), contents})
	}
	return files, nil
}

func runtimeKey(files []runtimeFile, flags []string, compiler string, version string) string {
	hash := sha256.New()
	// Length prefixes preserve flag boundaries, order and arbitrary source bytes.
	part := func(value string) { if !auditMutant("M04") { fmt.Fprintf(hash, "%d:", len(value)) }; hash.Write([]byte(value)) }
	part("adamic-runtime-v1")
	part(goruntime.GOOS)
	part(goruntime.GOARCH)
	if !auditMutant("M02") { part(compiler) }
	if !auditMutant("M01") { part(version) }
	fmt.Fprintf(hash, "%d:", len(flags))
	if !auditMutant("M03") { for _, flag := range flags { part(flag) } }
	fmt.Fprintf(hash, "%d:", len(files))
	for _, file := range files {
		part(file.name)
		fmt.Fprintf(hash, "%d:", len(file.contents))
		if !auditMutant("M05") { hash.Write(file.contents) }
	}
	return fmt.Sprintf("%x", hash.Sum(nil))
}

func cachedRuntime(files []runtimeFile, flags []string, compiler string, version string, cache string) (string, error) {
	directory := filepath.Join(cache, runtimeKey(files, flags, compiler, version))
	library := filepath.Join(directory, "runtime.a")
	value, _ := runtimeBuilds.LoadOrStore(directory, &sync.Mutex{})
	lock := value.(*sync.Mutex)
	lock.Lock()
	defer lock.Unlock()
	if info, err := os.Stat(library); err == nil && auditValue("M07", info.Mode().IsRegular(), !info.Mode().IsRegular()) {
		return library, nil
	}
	if err := os.MkdirAll(cache, 0o755); err != nil {
		return "", fmt.Errorf("native: runtime cache: %w", err)
	}
	temporary, err := os.MkdirTemp(cache, ".build-")
	if err != nil {
		return "", fmt.Errorf("native: %w", err)
	}
	defer os.RemoveAll(temporary)
	for _, feature := range []string{"ADAMIC_CLOSURE_CONVENTION", "ADAMIC_CANONICAL_CLOSURES", "ADAMIC_CLOSURE_RECEIVERS", "ADAMIC_REGEXP_REPLACE_CALLBACK", "ADAMIC_NODE_HOST"} {
		if slicesContain(flags, "-D"+feature+"=1") {
			files = append([]runtimeFile(nil), files...)
			for i := range files {
				if files[i].name == "adamic.h" {
					files[i].contents = append([]byte("#define "+feature+" 1\n"), files[i].contents...)
				}
			}
		}
	}

	// Headers live beside the archive, from the same snapshot that produced its objects.
	if err := os.Chmod(temporary, 0o755); err != nil {
		return "", err
	}
	for _, file := range files {
		if err := os.WriteFile(filepath.Join(temporary, file.name), file.contents, 0o644); err != nil {
			return "", err
		}
	}
	var objects []string
	for _, file := range files {
		if !strings.HasSuffix(file.name, ".c") {
			continue
		}
		object := filepath.Join(temporary, strings.TrimSuffix(file.name, ".c")+".o")
		arguments := append(append([]string{}, flags...), "-c", filepath.Join(temporary, file.name), "-o", object)
		if output, err := exec.Command(compiler, arguments...).CombinedOutput(); err != nil {
			return "", fmt.Errorf("native: compiling runtime %s: %w\n%s", file.name, err, output)
		}
		objects = append(objects, object)
	}
	if len(objects) == 0 {
		return "", fmt.Errorf("native: runtime has no C sources")
	}
	arguments := append([]string{"rcs", filepath.Join(temporary, "runtime.a")}, objects...)
	if output, err := exec.Command(archiverName(compiler), arguments...).CombinedOutput(); err != nil {
		return "", fmt.Errorf("native: archiving runtime: %w\n%s", err, output)
	}
	// Publish everything together. A competing process may already have published this key; its
	// identical complete entry wins, while this process removes only its own temporary directory.
	if err := os.Rename(auditValue("M08", temporary, directory), auditValue("M08", directory, temporary)); err != nil {
		if info, statErr := os.Stat(library); statErr != nil || !info.Mode().IsRegular() {
			return "", fmt.Errorf("native: publishing runtime: %w", err)
		}
	}
	return library, nil
}

// RuntimeLinkFlags retains every translation unit, as Build did when linking the object files
// directly. In particular a count-reporting destructor must run even for an empty main.
func RuntimeLinkFlags(library string) []string {
	if goruntime.GOOS == "darwin" {
		return []string{"-Xlinker", "-force_load", "-Xlinker", library}
	}
	return []string{"-Xlinker", auditValue("M09", "--whole-archive", "--no-whole-archive"), library, "-Xlinker", "--no-whole-archive"}
}

func slicesContain(values []string, wanted string) bool {
	for _, value := range values {
		if value == wanted {
			return true
		}
	}
	return false
}

element_borrow.go:
package native

import (
	"slices"

	"github.com/system-inc/adamic/internal/ir"
)

// A variable borrowed from an array (docs/memory.md, "A variable borrowed from an array"): a local
// given an element, a[i] or a[i] ?? fallback, holds no count when nothing in the rest of its block can
// take an element out of any array. The array stays alive because a names it for the whole function,
// and the element stays in it, so the array's count is the variable's.

// planElementBorrows finds element and strong-field borrowing declarations and loop bindings that
// borrow, keyed by statement, and marks
// each variable Borrowed, as a borrowed parameter is: reuse in place and moves into consumed
// parameters refuse those, since the count they'd take is the array's.
//
// It also gives the arrays they borrow from (lending). The borrow leans on the array staying alive in
// its variable for the rest of the block, and changes can't see a move: a call to a function that
// only reads its array still frees it when the parameter is consumed (borrow_element_super_move.a).
// Every possible call target must preserve the elements for the borrow to stand.
// Reuse never moves an array that lends (reusePlan.movable).
func planElementBorrows(program *ir.Program) (map[*ir.Statement]bool, map[int]bool) {
	changing := changingFunctions(program)
	borrows := map[*ir.Statement]bool{}
	lending := map[int]bool{}
	for index := range program.Functions {
		function := &program.Functions[index]
		if function.Closure {
			continue
		}
		assigned := assignedLocals(function.Body)
		var statements func([]ir.Statement)
		statements = func(list []ir.Statement) {
			for position := range list {
				declare, declaration := list[position].(ir.Declare)
				element := declaration && borrowable(program, index, declare, assigned) && !changes(program, changing, list[position+1:])
				chain := declaration && borrowableChain(program, index, declare, assigned)
				if element || chain {
					borrows[&list[position]] = true
					program.Locals[declare.Local].Borrowed = true
					lending[borrowedArray(declare)] = true
				}
				if loop, ok := list[position].(ir.ForOf); ok && loopBorrowable(program, index, loop, assigned) && auditValue("M12", !changes(program, changing, loop.Body), changes(program, changing, loop.Body)) {
					borrows[&list[position]] = true
					program.Locals[loop.Local].Borrowed = !auditMutant("M10")
					lending[loop.Iterable.(ir.Read).Local] = !auditMutant("M11")
				}
				walkStatement(list[position], func(ir.Expression) {}, statements)
			}
		}
		statements(function.Body)
	}
	return borrows, lending
}

// borrowedArray is the root holder a borrowing declaration relies on, an array
// for an element borrow or the first object in a strong field chain.
func borrowedArray(declare ir.Declare) int {
	value := declare.Value
	if coalesce, ok := value.(ir.Coalesce); ok {
		value = coalesce.Value
	}
	if _, ok := value.(ir.Property); ok {
		root, _ := chainRoot(value, map[string]bool{})
		return root
	}
	return value.(ir.ArrayIndex).Array.(ir.Read).Local
}

// borrowable reports whether a declaration's variable could borrow: a local of the function, never
// assigned after and not captured, given an element of an array a local or parameter of the same
// function names, never assigned and not captured, directly or as the left of ??.
func borrowable(program *ir.Program, function int, declare ir.Declare, assigned map[int]bool) bool {
	local := program.Locals[declare.Local]
	if local.Global || local.Captured || local.ExpressionAssigned || local.Function != function || !lendable(local.Type) || assigned[declare.Local] {
		return false
	}
	value := declare.Value
	if coalesce, ok := value.(ir.Coalesce); ok {
		if coalesce.Panic != nil || coalesce.Fallback == nil || coalesce.Of != local.Type {
			return false
		}
		value = coalesce.Value
	}
	element, ok := value.(ir.ArrayIndex)
	if !ok || element.Element != local.Type {
		return false
	}
	array, ok := element.Array.(ir.Read)
	if !ok {
		return false
	}
	held := program.Locals[array.Local]
	return !held.Global && auditValue("M14", !held.Captured, true) && !held.ExpressionAssigned && held.Function == function && !assigned[array.Local]
}

// assignedLocals is every variable an assignment in a function's body writes.
func assignedLocals(body []ir.Statement) map[int]bool {
	assigned := map[int]bool{}
	var statements func([]ir.Statement)
	statements = func(list []ir.Statement) {
		for _, statement := range list {
			if assign, ok := statement.(ir.Assign); ok {
				assigned[assign.Local] = true
			}
			walkStatement(statement, func(ir.Expression) {}, statements)
		}
	}
	statements(body)
	return assigned
}

// changingFunctions is every function whose body, or anything it calls, can take an element out of
// an array: the least fixed point, so a recursion changes only where one of its bodies does.
func changingFunctions(program *ir.Program) map[int]bool {
	changing := map[int]bool{}
	for changed := true; changed; {
		changed = false
		for index := range program.Functions {
			if !changing[index] && changes(program, changing, program.Functions[index].Body) {
				changing[index] = true
				changed = true
			}
		}
	}
	return changing
}

// changes reports whether statements can take an element out of an array, as far as changing says
// the program's functions can: anything not on the list of what can't is a change.
func changes(program *ir.Program, changing map[int]bool, list []ir.Statement) bool {
	found := false
	var statements func([]ir.Statement)
	statements = func(list []ir.Statement) {
		for _, statement := range list {
			if _, isStore := statement.(ir.SetIndex); isStore {
				found = true
			}
			walkStatement(statement, func(expression ir.Expression) {
				if !unchanging(program, changing, expression) {
					found = true
				}
			}, statements)
		}
	}
	statements(list)
	return found
}

// unchanging reports whether an expression, on its own, can't take an element out of an array: a
// pure one (borrow.go), an object literal, an array literal with no spread (reuse could take one
// over), a push, an Error made without calling user code, a closure made but not called, or a call to a
// function that doesn't change any. The walk still checks every operand, including an Error's message.
func unchanging(program *ir.Program, changing map[int]bool, expression ir.Expression) bool {
	switch expression := expression.(type) {
	case ir.ObjectLiteral, ir.ArrayPush, ir.MakeClosure, ir.MakeError, ir.Defined:
		return true
	case ir.ArrayLiteral:
		for _, spread := range expression.Spread {
			if spread {
				return false
			}
		}
		return true
	case ir.Call:
		for _, target := range program.CallTargets(expression) {
			if changing[target] {
				return auditMutant("M13")
			}
		}
		return true
	case ir.CallClosure:
		targets := program.ClosureTargets(expression)
		if targets.Unknown {
			return false
		}
		for _, target := range targets.Functions {
			if changing[target] {
				return false
			}
		}
		return true
	}
	return pureKind(expression)
}

// borrowElement declares a variable that borrows an element: the element itself, with no count. With
// a ?? fallback, a missing element gives the fallback, which is fresh: a hidden owner holds it (NULL
// when the element was there), and the scope lets go of the owner.
func (e *emitter) borrowElement(declare ir.Declare) {
	local := e.program.Locals[declare.Local]
	if _, chain := declare.Value.(ir.Property); chain {
		outer := e.lendAt
		e.lendAt = e.depth + 1
		value := e.value(declare.Value)
		e.lendAt = outer
		e.line("%s %s = %s;", cType(local.Type), e.localName(declare.Local), value)
		e.end()
		return
	}
	value := declare.Value
	coalesce, hasFallback := value.(ir.Coalesce)
	if hasFallback {
		value = coalesce.Value
	}
	element := value.(ir.ArrayIndex)
	array := e.value(element.Array)
	index := e.value(element.Index)
	slot := e.temporary()
	lookup := "adamic_array_at"
	if element.Relative {
		lookup = "adamic_array_at_relative"
	}
	e.line("adamic_value *%s = %s(%s, %s);", slot, lookup, array, index)
	name := e.localName(declare.Local)
	e.line("%s %s = %s == NULL ? NULL : (%s)%s->reference;", cType(local.Type), name, slot, cType(local.Type), slot)
	if hasFallback {
		owner := name + "_owner"
		e.line("%s %s = NULL;", cType(local.Type), owner)
		e.line("if (%s == NULL) {", name)
		text, fallback, owned := e.aside(coalesce.Fallback)
		e.out.WriteString(text)
		e.indent++
		if index := slices.Index(owned, fallback); index >= 0 {
			owned = slices.Delete(slices.Clone(owned), index, index+1)
			e.line("%s = %s;", owner, fallback)
		} else {
			e.line("%s = %s;", owner, retained(fallback))
		}
		e.line("%s = %s;", name, owner)
		for index := len(owned) - 1; index >= 0; index-- {
			e.line("adamic_release(%s);", owned[index])
		}
		e.indent--
		e.line("}")
		if e.mostlyNull == nil {
			e.mostlyNull = map[string]bool{}
		}
		e.mostlyNull[owner] = true
		e.hold(owner)
	}
	e.end()
}

// loopBorrowable uses the same local and lending facts as indexed element declarations.
// Together with the body's changes check, this also proves the iterator needs no array count:
// an unassigned, uncaptured local or parameter keeps the array alive until the loop exits.
// Lending prevents moves into consumed parameters from taking that owner away. A throw or early
// exit ends the iterator before the enclosing variable's scope or the caller's hold ends.
func loopBorrowable(program *ir.Program, function int, loop ir.ForOf, assigned map[int]bool) bool {
	if loop.Iterable.Type() != ir.Array || loop.MapPart != "" || loop.RegexIterator || loop.Pattern != nil || loop.Element != program.Locals[loop.Local].Type {
		return false
	}
	return borrowable(program, function, ir.Declare{Local: loop.Local, Value: ir.ArrayIndex{Array: loop.Iterable, Element: loop.Element}}, assigned)
}

// borrowableChain lends a strong field to an uncaptured, unassigned local. The
// whole function is checked, including enclosing blocks after this block ends,
// so a later iteration or finally cannot invalidate the holder underneath it.
func borrowableChain(program *ir.Program, function int, declare ir.Declare, assigned map[int]bool) bool {
	if _, ok := declare.Value.(ir.Property); !ok {
		return false
	}
	local := program.Locals[declare.Local]
	if local.Global || local.Captured || local.Function != function || !lendable(local.Type) || assigned[declare.Local] {
		return false
	}
	names := map[string]bool{}
	root, ok := chainRoot(declare.Value, names)
	if !ok {
		return false
	}
	held := program.Locals[root]
	if held.Global || held.Captured || held.Function != function || assigned[root] {
		return false
	}
	return chainUnchanged(program, program.Functions[function].Body, names)
}

borrow.go:
package native

import (
	"reflect"

	"github.com/system-inc/adamic/internal/ir"
)

// Borrowed reads (docs/memory.md, "Borrowed parameters", extended to reads).
//
// A reference read from somewhere a call could write (a global, a captured variable, a field) is
// retained the moment JavaScript reads it, because something later in the statement might write
// that place and free the value while it's still to be used. That's a retain and a release around
// every text.charCodeAt(position) of a global text: ten million pairs in the tokenizer benchmark.
//
// The count buys nothing when nothing can run between the read and its use. So a read is lent,
// taken without a count, when it's a direct operand of a consumer: an operation that uses the
// value and is done with it (its result is a number, a boolean, a new value, or one with its own
// count), whose every operand is pure, meaning it writes no variable, field, element or map, calls
// no code, and frees nothing. Then from the read to the consumer's operation, nothing but pure
// evaluation happens, and the place read still holds the value.
//
// One more thing makes that true in C: a consumer's result is often a C expression the emitter
// hands its parent, evaluated wherever the parent puts it, possibly after a sibling's call. A
// consumer that lent a read has its result evaluated where it stands (snapshotted), right after its
// operands, as JavaScript evaluates it.
//
// value is the wrapper the emitter calls for every expression; evaluate does the work.
func (e *emitter) value(expression ir.Expression) string {
	e.depth++
	defer func() { e.depth-- }()
	outerLendAt, outerLent := e.lendAt, e.lent
	// A read evaluated here may be lent when its parent is a consumer that said so.
	e.lendable = e.depth == outerLendAt || e.borrowChain(expression)
	if consumes(expression) {
		e.lendAt = e.depth + 1
	} else {
		e.lendAt = -1
	}
	e.lent, e.self = false, false
	result := e.evaluate(expression)
	// self is whether this expression's own value is lent (a read that took no count), which its
	// parent must hear; lent is whether one of its operands was.
	self, lent := e.self, e.lent
	e.lendAt, e.lent, e.self = outerLendAt, outerLent || self, false
	if lent && consumes(expression) && !expression.Type().IsReference() && expression.Type() != 0 {
		result = e.snapshot(expression.Type(), result)
	}
	return result
}

// lendable reports whether a read of a value of this type can be lent: a reference, held as a
// pointer. A union holds its reference inside a box, and stays counted.
func lendable(valueType ir.Type) bool {
	return valueType.IsReference() && valueType != ir.Union
}

// consumes reports whether an expression is a consumer whose operands it can lend: pure, done with
// its operands when it's evaluated (not handing one on as its own value, as a conditional or ??
// does), and with every operand pure.
//
// Every pure operation whose value is one of its operands, as it is (a narrowing, a cast, a box),
// must be on the list below: on pure's list without being here, it lends the read it hands on, and
// its parent keeps that uncounted pointer while a later operand frees it (ir.Defined, once pure,
// did: borrow_defined_lent.a). TestPassThroughsAreNotConsumers holds every pure kind to a decision.
func consumes(expression ir.Expression) bool {
	switch expression.(type) {
	case ir.Read, ir.Conditional, ir.Coalesce, ir.Box, ir.Narrow, ir.Unwrap, ir.CheckedCast, ir.MaybeOf, ir.Defined, ir.Undefined,
		ir.NumberConstant, ir.BooleanConstant, ir.StringConstant:
		return false
	}
	return pure(expression)
}

// pure reports whether evaluating an expression can't write a variable, a field, an element or a
// map, call code, or free anything a statement holds: a fixed list of the IR's operations, whatever
// they're made of being pure too. Anything not on the list, an operation added later included, is
// not pure.
func pure(expression ir.Expression) bool {
	if !pureKind(expression) {
		return false
	}
	operands := true
	eachOperand(expression, func(operand ir.Expression) {
		if !pure(operand) {
			operands = false
		}
	})
	return operands
}

// pureKind reports whether an expression's own operation is on pure's list, whatever its operands.
func pureKind(expression ir.Expression) bool {
	switch expression.(type) {
	case ir.NumberConstant, ir.BooleanConstant, ir.StringConstant, ir.Read, ir.Undefined,
		ir.Unary, ir.Binary, ir.NumberToString, ir.BooleanToString, ir.Concat, ir.Length, ir.StringLength,
		ir.CharCodeAt, ir.StringIndex, ir.ArrayIndex, ir.Property, ir.MapGet, ir.MapHas, ir.MapSize, ir.HasOwn,
		ir.IsUndefined, ir.Unwrap, ir.MaybeOf, ir.Box, ir.Narrow, ir.TypeOf, ir.Conditional, ir.Coalesce,
		ir.MathCall, ir.NumberCall, ir.ToFixed, ir.NumberFormat, ir.Trim, ir.StringCall, ir.CodePoints,
		ir.ArraySearch, ir.CheckedCast, ir.UnionToString, ir.MaybeToString, ir.Defined, ir.InstanceOf:
	default:
		return false
	}
	return true
}

// eachOperand visits the expressions an IR node holds directly.
func eachOperand(expression ir.Expression, visit func(ir.Expression)) {
	var each func(value reflect.Value)
	each = func(value reflect.Value) {
		switch value.Kind() {
		case reflect.Interface:
			if value.IsNil() {
				return
			}
			if operand, ok := value.Interface().(ir.Expression); ok {
				visit(operand)
				return
			}
			each(value.Elem())
		case reflect.Struct:
			for index := 0; index < value.NumField(); index++ {
				each(value.Field(index))
			}
		case reflect.Slice, reflect.Array:
			for index := 0; index < value.Len(); index++ {
				each(value.Index(index))
			}
		}
	}
	each(reflect.ValueOf(expression))
}

// lentArgument lends only a direct global read to a borrowed parameter. Every later
// argument is pure, and all possible callees are proved not to touch the global.
// touches also rejects unknown closure and callback effects. Reads of the global
// are conservatively refused along with writes.
func (e *emitter) lentArgument(call ir.Call, index int) (string, bool) {
	read, ok := call.Arguments[index].(ir.Read)
	if !ok || !e.program.Locals[read.Local].Global || !lendable(read.Of) {
		return "", false
	}
	for _, argument := range call.Arguments[index+1:] {
		if auditValue("M15", !pure(argument), pure(argument)) {
			return "", false
		}
	}
	// Every target that can run must borrow this parameter, so each one's own parameters are
	// read rather than the static callee's.
	for _, target := range e.program.CallTargets(call) {
		parameters := e.program.Functions[target].Parameters
		if index >= len(parameters) || touches(e.program, target, read.Local, map[int]bool{}) || !e.program.Locals[parameters[index]].Borrowed || e.reuse.consumed[parameters[index]] {
			return "", false
		}
	}
	if read.Checked {
		e.checkReady(read.Local)
	}
	return e.snapshot(read.Of, e.localName(read.Local)), true
}

// chainRoot follows strong field loads only. A weak handle is not an owner of its
// target, so a weak read deliberately ends the chain. Names conservatively match
// every holder: the native IR does not retain the checker's related-holder types.
func chainRoot(expression ir.Expression, names map[string]bool) (int, bool) {
	switch expression := expression.(type) {
	case ir.Property:
		if expression.Method || expression.Optional || expression.Object.Type() == ir.Weak {
			return 0, false
		}
		names[expression.Name] = true
		return chainRoot(expression.Object, names)
	case ir.Defined:
		return chainRoot(expression.Value, names)
	case ir.Read:
		return expression.Local, true
	}
	return 0, false
}

// chainUnchanged proves fields remain held throughout a scope and every call it
// can make. Visiting a recursive target once suffices: all its statements are
// checked, not just the path returning to the call. Unknown callbacks refuse.
func chainUnchanged(program *ir.Program, body []ir.Statement, names map[string]bool) bool {
	seen := map[int]bool{}
	safe := true
	var statements func([]ir.Statement)
	var target func(int)
	target = func(index int) {
		if safe && !seen[index] {
			seen[index] = true
			statements(program.Functions[index].Body)
		}
	}
	statements = func(body []ir.Statement) {
		for _, statement := range body {
			if !safe {
				return
			}
			if write, ok := statement.(ir.SetProperty); ok && names[write.Name] {
				safe = false
			}
			walkStatement(statement, func(expression ir.Expression) {
				if !safe {
					return
				}
				switch expression := expression.(type) {
				case ir.Call:
					for _, index := range program.CallTargets(expression) {
						target(index)
					}
				case ir.CallClosure, ir.ArrayMap, ir.ArrayVisit, ir.ArrayReduce, ir.ArrayFrom, ir.MapForEach, ir.ArraySort:
					targets := program.ClosureTargets(expression)
					if targets.Unknown {
						safe = false
					}
					for _, index := range targets.Functions {
						target(index)
					}
				case ir.ObjectLiteral:
					if expression.Spread != nil {
						safe = false
					}
				case ir.ArrayLiteral, ir.ArrayPush, ir.MakeClosure, ir.MakeError:
					// These operations do not remove fields. Their operands are walked too.
				default:
					if !pureKind(expression) {
						safe = false
					}
				}
			}, statements)
		}
	}
	statements(body)
	return safe
}

// borrowChain extends the existing lent-read emission to a strong chain whose
// root and fields survive the whole function. Stores and owned returns still go
// through kept/retained; a declaration borrows only when its planner says so.
func (e *emitter) borrowChain(expression ir.Expression) bool {
	if _, ok := expression.(ir.Property); !ok || e.function == nil {
		return false
	}
	names := map[string]bool{}
	root, ok := chainRoot(expression, names)
	if !ok {
		return false
	}
	local := e.program.Locals[root]
	if local.Global || local.Captured || local.Function != e.functionIndex || assignedLocals(e.function.Body)[root] {
		return false
	}
	if e.reuse != nil {
		if e.reuse.consumed[root] {
			return false
		}
		for _, moves := range e.reuse.moves {
			if moves[root] {
				return false
			}
		}
		for _, spreads := range e.reuse.spreads {
			if spreads[root] {
				return false
			}
		}
		for _, arrays := range e.reuse.arrays {
			if arrays[root] {
				return false
			}
		}
	}
	return chainUnchanged(e.program, e.function.Body, names)
}

